<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Session\Domain;

/**
 * Snapshot of an active OAuth authorization session stored between authentication steps.
 *
 * Loaded from the session store when the authorization endpoint resumes an in-progress flow,
 * for example after an MFA challenge. The csid (cross-session identifier) is a stable value
 * derived from the user's long-lived browser cookie that allows the system to locate existing
 * sessions without exposing the internal state token. The withMfa flag is set to true only
 * after a successful second-factor step and may be required by certain clients before token
 * issuance proceeds.
 *
 * The session is published to relying parties (sid claim, logout notifications) only through
 * publicSid, a random identifier unrelated to the session cookie, so no token or URL lets anyone
 * rebuild the user's session credential.
 */
class SessionInfo
{
    /**
     * Stable cross-session identifier derived from the user's browser cookie.
     * Allows the system to correlate multiple in-flight authorization sessions for the same user.
     */
    public readonly string $csid;

    /**
     * Indicates whether the user has successfully completed an MFA challenge in this session.
     * Clients that require MFA must check this flag before allowing token issuance.
     */
    public readonly bool $withMfa;

    /**
     * The issuer URL associated with this session, identifying the tenant's OIDC provider endpoint.
     */
    public readonly string $issuer;

    /**
     * Unique identifier of the authenticated user within the tenant.
     * Used to look up the user's profile and claims when building tokens.
     */
    public readonly string $userId;

    /**
     * OAuth client identifier that initiated the authorization flow for this session.
     * Stored to validate that the token request comes from the same client.
     */
    public readonly string $clientId;

    /**
     * Other clients that obtained an authorization from this session through SSO.
     *
     * @var string[]
     */
    public readonly array $ssoClients;

    /**
     * @param string[] $ssoClients
     * @param string[] $amr
     */
    public function __construct(
        string $csid,
        bool $withMfa,
        string $issuer,
        string $userId,
        string $clientId,
        array $ssoClients = [],
        /** Public identifier of the session, published as the sid claim; never the cookie value. */
        public readonly string $publicSid = '',
        /** When the user actually authenticated, carried as auth_time; null when unknown. */
        public readonly ?\DateTimeImmutable $authTime = null,
        /** Authentication methods actually used (RFC 8176), only those with evidence. */
        public readonly array $amr = [],
        /** Authentication context class reference; null until the login maps a configured value (task 067). */
        public readonly ?string $acr = null,
        /** Uid of the tenant the session was opened in, when recorded. */
        public readonly ?string $tenantId = null,
    ) {
        $this->csid = $csid;
        $this->withMfa = $withMfa;
        $this->issuer = $issuer;
        $this->userId = $userId;
        $this->clientId = $clientId;
        $this->ssoClients = $ssoClients;
    }

    /**
     * Returns true when the client opened this session or joined it later through SSO.
     */
    public function hasClient(string $clientId): bool
    {
        return in_array($clientId, $this->clients(), true);
    }

    /**
     * Relying parties that take part in this session: the one that opened it followed by those
     * that joined it through SSO. Only these must be notified when the session ends.
     *
     * @return string[]
     */
    public function clients(): array
    {
        return array_values(array_unique([$this->clientId, ...$this->ssoClients]));
    }
}
